"""Generate committed, build-free GitHub Pages output. Dev-only: Pillow + lxml."""
from pathlib import Path
from html import escape as esc
import json
ROOT=Path(__file__).resolve().parents[1]
BASE='https://staywhiteswan.com'
from photography import legacy_image as image
def head(lang,path,title,description,other,kind='home'):
 en=path if lang=='en' else other; es=other if lang=='en' else path
 schema={'@context':'https://schema.org','@type':'LodgingBusiness','@id':BASE+'/#villa','name':'White Swan Villa','url':BASE+path,'description':description,'telephone':'+50370528003','address':{'@type':'PostalAddress','addressLocality':'Tamanique','addressRegion':'La Libertad','addressCountry':'SV'},'image':BASE+'/assets/editorial/villa-light-1536.webp','sameAs':['https://www.airbnb.com/rooms/47911834']} if kind=='home' else {'@context':'https://schema.org','@type':'WebPage','name':title,'url':BASE+path,'inLanguage':lang}
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{BASE+path}"><link rel="alternate" hreflang="en" href="{BASE+en}"><link rel="alternate" hreflang="es" href="{BASE+es}"><link rel="alternate" hreflang="x-default" href="{BASE+en}"><meta name="theme-color" content="#2e3b36"><meta property="og:image" content="https://staywhiteswan.com/assets/editorial/villa-light-1536.webp"><meta name="twitter:card" content="summary_large_image"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{BASE+path}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><link rel="stylesheet" href="/assets/editorial.css"><link rel="stylesheet" href="/assets/retreat.css"><link rel="stylesheet" href="/assets/guide.css"><link rel="stylesheet" href="/assets/hospitality.css"><script src="/assets/guest-experience.js" defer></script><script src="/assets/retreat.js" defer></script><script src="/assets/gallery.js" defer></script><script src="/assets/config.js" defer></script><script src="/assets/site.js" defer></script></head>'''
from homepage import home as render_home, gallery as render_gallery, stay as render_stay, navigation, footer

def render(lang):
 return render_home(lang, head, image, components)

def components(lang):
 es=lang=='es';T=lambda en,sp:sp if es else en
 options=[('stay',T('A stay at the villa','Una estadía en la villa')),('private_chef',T('Private chef','Chef privado')),('in_home_massage',T('Massage','Masaje')),('grocery_shopping',T('Groceries','Compras')),('drinks_delivery',T('Drinks','Bebidas')),('airport_transfer',T('Airport transfer','Traslado del aeropuerto')),('car_rental',T('Car rental','Renta de auto')),('guided_tours',T('Tours','Paseos')),('decoration',T('Celebration','Celebración')),('other',T('Something else','Otra consulta'))]
 return f'''<dialog id="enquiry-dialog" aria-labelledby="enquiry-title"><button class="dialog-close" aria-label="{T('Close enquiry','Cerrar consulta')}">×</button><div class="form-heading"><span class="eyebrow">{T('YOUR STAY, THOUGHTFULLY PLANNED','TU ESTADÍA, CUIDANDO CADA DETALLE')}</span><h2 id="enquiry-title">{T('Let’s make it <em>yours.</em>','Hagámosla <em>tuya.</em>')}</h2><p>{T('Tell us a little about your plans. We’ll get back to you in English or Spanish.','Cuéntanos un poco sobre tus planes. Te responderemos en español o inglés.')}</p></div><form id="enquiry-form" hidden><label>{T('I’m interested in','Me interesa')}<select name="service">{''.join(f'<option value="{v}">{l}</option>' for v,l in options)}</select></label><label>{T('Your name','Tu nombre')}<input name="name" autocomplete="name" maxlength="100" minlength="2" required></label><div class="form-grid"><label>Email<input name="email" type="email" autocomplete="email" maxlength="160"></label><label>{T('Phone (with country code)','Teléfono (con código de país)')}<input name="phone" type="tel" autocomplete="tel" placeholder="+503 …" maxlength="30"></label></div><p class="fine">{T('Add an email or phone number so we can reply.','Agrega un correo o teléfono para poder responderte.')}</p><div class="form-grid"><label>{T('Arrival (optional)','Llegada (opcional)')}<input name="arrival" type="date"></label><label>{T('Departure (optional)','Salida (opcional)')}<input name="departure" type="date"></label></div><label>{T('Group size (optional)','Personas (opcional)')}<input name="guests" type="number" min="1" max="30"><span class="fine">{T('Confirm guest capacity on Airbnb when booking. Entering a group size here does not imply approval.','Confirma la capacidad en Airbnb al reservar. Indicar un tamaño de grupo aquí no implica aprobación.')}</span></label><label>{T('What would make this trip special?','¿Qué haría especial este viaje?')}<textarea name="message" maxlength="1600" rows="3"></textarea></label><p class="fine">{T('Please don’t send ID documents, payment card details or access codes.','No envíes documentos de identidad, datos de tarjetas ni códigos de acceso.')}</p><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input name="contactConsent" type="checkbox" required><span>{T('White Swan may use these details to respond to this enquiry. This is not consent to marketing.','White Swan puede usar estos datos para responder a esta consulta. Esto no autoriza mensajes de marketing.')} <a href="{('/es/privacidad/' if es else '/privacy/')}" target="_blank" rel="noopener">{T('Privacy details','Privacidad')}</a></span></label><p class="form-status" role="status" aria-live="polite"></p><button class="button submit" type="submit">{T('Send enquiry','Enviar consulta')} ↗</button><p class="fine">{T('No payment is taken. Your dates and services are confirmed separately.','No se cobra ningún pago. Las fechas y servicios se confirman por separado.')}</p></form><div class="enquiry-success" hidden><h3>{T('Your enquiry is with us.','Recibimos tu consulta.')}</h3><p class="receipt"></p><p>{T('You can continue on WhatsApp with your enquiry reference. Opening WhatsApp does not send a message automatically.','Puedes continuar en WhatsApp con tu referencia. Abrir WhatsApp no envía un mensaje automáticamente.')}</p><a class="button whatsapp-continuation" target="_blank" rel="noopener">{T('Continue on WhatsApp','Continuar en WhatsApp')} ↗</a></div><p class="enquiry-fallback"><a href="https://wa.me/50370528003" target="_blank" rel="noopener">{T('Prefer WhatsApp? Message us directly','¿Prefieres WhatsApp? Escríbenos directamente')} ↗</a></p></dialog><aside class="cookie-panel" aria-label="{T('Analytics preferences','Preferencias de analítica')}" hidden><p>{T('May we measure how this website is used? Optional analytics helps us improve the experience. Your enquiry works either way.','¿Podemos medir el uso de esta web? La analítica opcional nos ayuda a mejorar. Tu consulta funciona de cualquier manera.')}</p><div><button class="button small" data-consent="granted">{T('Allow analytics','Permitir analítica')}</button><button class="button outline small" data-consent="denied">{T('No thanks','No, gracias')}</button></div></aside>'''

for lang in ['en','es']:
 path=ROOT/('es' if lang=='es' else '');path.mkdir(exist_ok=True);(path/'index.html').write_text(render(lang))
 # The original template supplies content, never the retired layout.
 from guestguide import guide as render_guide
 target='/es/guia/' if lang=='es' else '/guide/'
 out=ROOT/target.strip('/');out.mkdir(parents=True,exist_ok=True)
 (out/'index.html').write_text(render_guide(lang,head,components))
 privacy='/es/privacidad/' if lang=='es' else '/privacy/';other='/privacy/' if lang=='es' else '/es/privacidad/'
 T=lambda en,sp:sp if lang=='es' else en
 privacybody=f'''<body class="editorial privacy-page" id="top">{navigation(lang,"privacy")}<main id="main" class="section privacy"><span class="eyebrow">WHITE SWAN / {T('YOUR INFORMATION','TUS DATOS')}</span><h1>{T('Privacy & your choices','Privacidad y tus decisiones')}</h1><p>{T('When you send an enquiry, White Swan uses your name, contact details, dates and message to respond and coordinate your requested stay or services. This form does not subscribe you to marketing.','Al enviar una consulta, White Swan usa tu nombre, contacto, fechas y mensaje para responder y coordinar tu estadía o servicios. Este formulario no te suscribe a marketing.')}</p><h2>{T('Your enquiry','Tu consulta')}</h2><p>{T('Enquiries are stored in our intake service and private operations workspace, hosted on OpenAI Sites and Cloudflare infrastructure. Only authorized operators can read the intake feed. Relevant service details may be shared with a supplier when coordinating a service you request. Do not include identity documents, card details or access codes.','Las consultas se guardan en nuestro servicio de recepción y espacio privado de operaciones, alojados en infraestructura de OpenAI Sites y Cloudflare. Solo operadores autorizados pueden leer las consultas. Los detalles pertinentes pueden compartirse con un proveedor al coordinar un servicio solicitado. No incluyas documentos de identidad, datos de tarjetas ni códigos de acceso.')}</p><h2>{T('Optional analytics','Analítica opcional')}</h2><p>{T('With your permission, we record page views, enquiry opens and outbound WhatsApp/Airbnb clicks, with the page, service, language and limited campaign labels. These events exclude your name, email, phone and message. We remember your analytics choice on this device. We do not currently load a Google Analytics tag.','Con tu permiso registramos vistas de página, apertura de consultas y clics hacia WhatsApp/Airbnb, con página, servicio, idioma y etiquetas limitadas de campaña. Los eventos excluyen tu nombre, correo, teléfono y mensaje. Guardamos tu preferencia en este dispositivo. Actualmente no cargamos una etiqueta de Google Analytics.')}</p><button class="button" data-cookie-settings>{T('Change analytics preference','Cambiar preferencia de analítica')}</button><h2>{T('External services','Servicios externos')}</h2><p>{T('This website is hosted on GitHub Pages and loads fonts from Google Fonts. Airbnb and WhatsApp operate under their own privacy policies when you follow their links. Concierge links prefill the topic, website page and preferred language in WhatsApp for you to review. A WhatsApp click does not automatically send a message. Technical hosting logs may be retained by infrastructure providers.','Esta web se aloja en GitHub Pages y carga fuentes de Google Fonts. Airbnb y WhatsApp aplican sus propias políticas al seguir sus enlaces. Los enlaces de concierge preparan el tema, la página web y el idioma preferido en WhatsApp para que los revises. Un clic en WhatsApp no envía un mensaje automáticamente. Los proveedores de infraestructura pueden conservar registros técnicos.')}</p><h2>{T('Questions or deletion requests','Consultas o solicitudes de eliminación')}</h2><p>{T('Contact White Swan to request access, correction or deletion of enquiry information. We retain enquiries for follow-up and service records; a fixed automated retention schedule is not yet configured.','Contacta a White Swan para solicitar acceso, corrección o eliminación de tus datos. Conservamos consultas para seguimiento y registros de servicio; aún no hay un plazo automatizado de eliminación configurado.')}</p><a class="text-link" href="https://wa.me/50370528003">{T('Contact White Swan on WhatsApp','Contactar a White Swan por WhatsApp')} ↗</a><p class="fine">{T('Updated 15 September 2026','Actualizado el 15 de septiembre de 2026')}</p></main>{footer(lang)}{components(lang)}</body></html>'''
 out=ROOT/privacy.strip('/');out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(head(lang,privacy,T('Privacy | White Swan','Privacidad | White Swan'),T('How White Swan handles enquiries and optional analytics.','Cómo White Swan gestiona consultas y analítica opcional.'),other,'privacy')+privacybody)
for lang in ['en','es']:
 out=ROOT/('es/fotos' if lang=='es' else 'photos');out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(render_gallery(lang,head,components))
for lang in ['en','es']:
 out=ROOT/('es/reservar' if lang=='es' else 'stay');out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(render_stay(lang,head,components))
paths=['/stay/','/es/reservar/','/','/es/','/guide/','/es/guia/','/privacy/','/es/privacidad/','/photos/','/es/fotos/']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p in paths)+'</urlset>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /content/\nDisallow: /scripts/\nSitemap: '+BASE+'/sitemap.xml\n')
for page in paths:
 output=ROOT/page.strip('/')/'index.html'
 output.write_text('\n'.join(line.rstrip() for line in output.read_text().splitlines())+'\n')
(ROOT/'.nojekyll').touch()
print('Generated ten localized pages, sitemap and responsive photographs.')
